use std::io::Read;
fn main(){let mut bytes=Vec::new();std::io::stdin().take(1024*1024+1).read_to_end(&mut bytes).unwrap();assert!(bytes.len()<=1024*1024);let rows:serde_json::Value=serde_json::from_slice(&bytes).unwrap();let mut result=Vec::new();for row in rows.as_array().unwrap(){let p=|k:&str|[row[k][0].as_f64().unwrap(),row[k][1].as_f64().unwrap()];let c=row["clip"].as_array().unwrap();let clip=[0,1,2,3].map(|i|i32::try_from(c[i].as_i64().unwrap()).unwrap());let spans=ingetrazo_render::qt_line::rasterize(p("a"),p("b"),row["width"].as_f64().unwrap(),clip,200000,100000).unwrap();result.push(spans.iter().map(|s|serde_json::json!([s.x,s.y,s.len,s.coverage])).collect::<Vec<_>>());}println!("{}",serde_json::to_string(&result).unwrap());}
